import { readFileSync } from 'node:fs';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import type { ModelDiagnosis } from '@on-par/factory-core';
import { getFactoryPaths } from '@on-par/factory-core';
import { RunLockHeldError, resolveBranchPrefix } from '@on-par/factory-core/internal';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import {
  assertValidProduct,
  AwaitingReviewError,
  CiFailedError,
  CiUnverifiedError,
  CliExitError,
  ConstitutionExistsError,
  createIngestHook,
  createSuperviseRunQueue,
  errorDetail,
  findOpenPRForIssue,
  findOpenPRNumber,
  formatDoctorReport,
  getCliVersion,
  getPullRequestLandState,
  hasReachableWorker,
  initConstitution,
  InvalidProductNameError,
  isPermanentMergeCheckError,
  IssueSkippedError,
  isPrMerged,
  isReviewRequiredMergeError,
  issueFromFactoryBranch,
  LandConflictError,
  LandFailureError,
  landOpenPullRequest,
  LaneParkError,
  listOpenFactoryPRs,
  main,
  markPullRequestReady,
  MERGE_CHECK_FAILURE_BUDGET_MS,
  MERGE_CHECK_MAX_CONSECUTIVE_FAILURES,
  parkEvents,
  parkReasonFor,
  PREREQUISITES_TEXT,
  prLookupFailure,
  readActiveProduct,
  resolveLaneBaseUrl,
  resolveUsageKnobs,
  runLane,
  scaffoldConstitution,
  squashMergeAndDelete,
  startLaneProxy,
  superviseLoop,
  sweepApprovedPRs,
  triageNoProposalError,
  triageProposalMessage,
  waitForMerge,
  withRepoRunLock,
} from './cli/index.js';

describe('cli', () => {
  const originalFactoryMerge = process.env.FACTORY_MERGE;
  const originalFactoryMergeAdmin = process.env.FACTORY_MERGE_ADMIN;

  beforeEach(() => {
    delete process.env.FACTORY_MERGE;
    delete process.env.FACTORY_MERGE_ADMIN;
  });

  afterEach(() => {
    if (originalFactoryMerge === undefined) {
      delete process.env.FACTORY_MERGE;
    } else {
      process.env.FACTORY_MERGE = originalFactoryMerge;
    }
    if (originalFactoryMergeAdmin === undefined) {
      delete process.env.FACTORY_MERGE_ADMIN;
    } else {
      process.env.FACTORY_MERGE_ADMIN = originalFactoryMergeAdmin;
    }
  });

  it('exports the main entrypoint', () => {
    expect(typeof main).toBe('function');
  });

  it('formats the triage proposal message with an accept hint for non-empty content', () => {
    const message = triageProposalMessage(
      'lane-a 1\nlane-b 2\n',
      '/repo/.factory/queue.proposed',
      '/repo/.factory/queue',
    );
    expect(message).toContain('lane-a 1\nlane-b 2');
    expect(message).toContain('factory triage accept');
  });

  it('returns null for empty or whitespace-only triage proposals', () => {
    expect(triageProposalMessage('', '/repo/.factory/queue.proposed', '/repo/.factory/queue')).toBeNull();
    expect(triageProposalMessage('   \n  ', '/repo/.factory/queue.proposed', '/repo/.factory/queue')).toBeNull();
  });

  describe('errorDetail', () => {
    it('prefers a trimmed stderr string over message', () => {
      expect(errorDetail({ stderr: '  boom on stderr  \n', message: 'boom message' })).toBe('boom on stderr');
    });

    it('falls back to message when stderr is absent or empty', () => {
      expect(errorDetail({ message: 'boom message' })).toBe('boom message');
      expect(errorDetail({ stderr: '', message: 'boom message' })).toBe('boom message');
      expect(errorDetail({ stderr: '   ', message: 'boom message' })).toBe('boom message');
    });

    it('falls back to String(err) for non-Error values', () => {
      expect(errorDetail('boom')).toBe('boom');
      expect(errorDetail(null)).toBe('null');
      expect(errorDetail(undefined)).toBe('undefined');
    });
  });

  describe('triageNoProposalError', () => {
    it('includes the planner failure detail when a planner error is present', () => {
      const err = triageNoProposalError(new Error('claude: command not found'));
      expect(err.code).toBe(1);
      expect(err.message).toContain('triage produced no proposal');
      expect(err.message).toContain('planner failed: claude: command not found');
    });

    it('is exactly the base message when there is no planner error', () => {
      const err = triageNoProposalError(undefined);
      expect(err.code).toBe(1);
      expect(err.message).toBe('triage produced no proposal');
    });
  });

  describe('prLookupFailure', () => {
    it('returns a LandFailureError with code 5 and the issue/branch/detail in the message', () => {
      const err = prLookupFailure(42, 'ship-it/42-x', new Error('rate limited'));
      expect(err).toBeInstanceOf(LandFailureError);
      expect(err.code).toBe(5);
      expect(err.message).toContain('#42');
      expect(err.message).toContain('ship-it/42-x');
      expect(err.message).toContain('rate limited');
    });
  });

  it('resolves usage knobs from defaults', () => {
    expect(resolveUsageKnobs({})).toEqual({
      cap: 227,
      stopAt: 0.75,
      resumeAt: 0.65,
      pollMs: 180_000,
      watch: true,
      estimator: false,
    });
  });

  it('resolves usage knobs from env overrides', () => {
    expect(
      resolveUsageKnobs({
        FACTORY_USAGE_CAP: '100',
        FACTORY_STOP_AT: '0.5',
        FACTORY_RESUME_AT: '0.4',
        FACTORY_USAGE_POLL: '60',
        FACTORY_USAGE_WATCH: '0',
        FACTORY_USAGE_ESTIMATOR: '1',
      }),
    ).toEqual({
      cap: 100,
      stopAt: 0.5,
      resumeAt: 0.4,
      pollMs: 60_000,
      watch: false,
      estimator: true,
    });
  });

  it('defaults estimator to false for any value other than "1"', () => {
    expect(resolveUsageKnobs({ FACTORY_USAGE_ESTIMATOR: 'true' }).estimator).toBe(false);
    expect(resolveUsageKnobs({}).estimator).toBe(false);
  });

  it('rejects invalid usage knob values with env var names', () => {
    expect(() => resolveUsageKnobs({ FACTORY_USAGE_CAP: '-5' })).toThrow(/FACTORY_USAGE_CAP/);
    expect(() => resolveUsageKnobs({ FACTORY_STOP_AT: '1.5' })).toThrow(/FACTORY_STOP_AT/);
    expect(() => resolveUsageKnobs({ FACTORY_RESUME_AT: '1.5' })).toThrow(/FACTORY_RESUME_AT/);
    expect(() => resolveUsageKnobs({ FACTORY_USAGE_POLL: 'abc' })).toThrow(/FACTORY_USAGE_POLL/);
  });

  it('takes the repo config cap over FACTORY_USAGE_CAP when both are set', () => {
    expect(resolveUsageKnobs({ FACTORY_USAGE_CAP: '100' }, { version: 1, usage: { capUsd: 50 } }).cap).toBe(50);
  });

  it('falls back to FACTORY_USAGE_CAP when no repo config is passed', () => {
    expect(resolveUsageKnobs({ FACTORY_USAGE_CAP: '100' }, null).cap).toBe(100);
  });

  function reading(pct: number, source: 'subscription' | 'estimate' = 'subscription') {
    return { pct, source, detail: `detail at ${Math.round(pct * 100)}%` };
  }

  it('waits for the resume gate, runs the queue, and loops again while STOP is present', async () => {
    const calls: any[] = [];
    const readings = [reading(0.9), reading(0.9), reading(0.5), reading(0.5)];
    const pathExistsResults = [true, false];
    let runQueueCalls = 0;

    await superviseLoop({
      cap: 1,
      resumeAt: 0.65,
      pollMs: 1000,
      stopFile: '/repo/.factory/STOP',
      eventsFile: '/repo/.factory/events.ndjson',
      now: false,
      readUsageFn: async () => readings.shift()!,
      pathExists: () => pathExistsResults.shift()!,
      clearStop: (path) => calls.push(['clearStop', path]),
      sleep: async () => {
        calls.push(['sleep']);
      },
      emitEvent: (_eventsFile: string, type: string, issue: string | number, msg: string) => {
        calls.push(['event', type, issue, msg]);
      },
      writeLine: (line) => calls.push(['writeLine', line]),
      runQueue: async () => {
        runQueueCalls++;
        calls.push(['runQueue']);
      },
    });

    expect(runQueueCalls).toBe(2);
    const firstRunQueueIdx = calls.findIndex((c) => c[0] === 'runQueue');
    const firstSleepIdx = calls.findIndex((c) => c[0] === 'sleep');
    expect(firstSleepIdx).toBeGreaterThanOrEqual(0);
    expect(firstSleepIdx).toBeLessThan(firstRunQueueIdx);

    const clearStopCalls = calls.filter((c) => c[0] === 'clearStop');
    expect(clearStopCalls).toHaveLength(2);

    const events = calls.filter((c) => c[0] === 'event');
    expect(events.filter((e) => e[1] === 'resumed')).toHaveLength(2);
    expect(events.filter((e) => e[1] === 'supervisor-done')).toHaveLength(1);
    expect(events[events.length - 1][1]).toBe('supervisor-done');
    expect(events[0][3]).toContain('(subscription)');
  });

  it('exits after one cycle when the queue drains without STOP present', async () => {
    const calls: any[] = [];

    await superviseLoop({
      cap: 1,
      resumeAt: 0.65,
      pollMs: 1000,
      stopFile: '/repo/.factory/STOP',
      eventsFile: '/repo/.factory/events.ndjson',
      now: true,
      readUsageFn: async () => reading(0.1),
      pathExists: () => false,
      clearStop: () => {},
      sleep: async () => {
        calls.push(['sleep']);
      },
      emitEvent: (_eventsFile: string, type: string) => {
        calls.push(['event', type]);
      },
      runQueue: async () => {
        calls.push(['runQueue']);
      },
    });

    expect(calls.filter((c) => c[0] === 'runQueue')).toHaveLength(1);
    expect(calls.filter((c) => c[0] === 'sleep')).toHaveLength(0);
    expect(calls.filter((c) => c[0] === 'event' && c[1] === 'supervisor-done')).toHaveLength(1);
  });

  it('skips the initial headroom wait when --now is set', async () => {
    const calls: any[] = [];

    await superviseLoop({
      cap: 1,
      resumeAt: 0.65,
      pollMs: 1000,
      stopFile: '/repo/.factory/STOP',
      eventsFile: '/repo/.factory/events.ndjson',
      now: true,
      readUsageFn: async () => reading(0.9),
      pathExists: () => false,
      clearStop: () => {},
      sleep: async () => {
        calls.push(['sleep']);
      },
      emitEvent: () => {},
      runQueue: async () => {
        calls.push(['runQueue']);
      },
    });

    expect(calls).toEqual([['runQueue']]);
  });

  it('re-checks the resume gate after each wait', async () => {
    const calls: any[] = [];
    const readings = [reading(0.9), reading(0.9), reading(0.5)];

    await superviseLoop({
      cap: 1,
      resumeAt: 0.65,
      pollMs: 1000,
      stopFile: '/repo/.factory/STOP',
      eventsFile: '/repo/.factory/events.ndjson',
      now: false,
      readUsageFn: async () => readings.shift()!,
      pathExists: () => false,
      clearStop: () => {},
      sleep: async () => {},
      emitEvent: () => {},
      writeLine: (line) => calls.push(line),
      runQueue: async () => {},
    });

    expect(calls).toHaveLength(2);
  });

  it('falls back to unavailable and stops waiting when a poll inside the resume gate returns null', async () => {
    const calls: any[] = [];
    const readings: Array<ReturnType<typeof reading> | null> = [reading(0.9), null];

    await superviseLoop({
      cap: 1,
      resumeAt: 0.65,
      pollMs: 1000,
      stopFile: '/repo/.factory/STOP',
      eventsFile: '/repo/.factory/events.ndjson',
      now: false,
      readUsageFn: async () => readings.shift() ?? null,
      pathExists: () => false,
      clearStop: () => {},
      sleep: async () => {
        calls.push(['sleep']);
      },
      emitEvent: () => {},
      writeLine: (line) => calls.push(['writeLine', line]),
      runQueue: async () => {
        calls.push(['runQueue']);
      },
    });

    expect(calls.filter((c) => c[0] === 'sleep')).toHaveLength(1);
    expect(calls).toContainEqual(['runQueue']);
